#!/usr/bin/env bash
# Run local Supabase acceptance checks on an isolated Linux CI runner.
set -Eeuo pipefail

env_file="$(mktemp "${RUNNER_TEMP:-/tmp}/student-law-supabase.XXXXXX")"
web_pid=''
cleanup() {
  if [[ -n "$web_pid" ]]; then
    kill "$web_pid" 2>/dev/null || true
    wait "$web_pid" 2>/dev/null || true
  fi
  rm -f -- "$env_file"
}
trap cleanup EXIT

npx supabase status -o env > "$env_file"
set -a
# This file is generated by the pinned Supabase CLI from the disposable CI stack.
source "$env_file"
set +a

export SUPABASE_URL="${API_URL:?Supabase API URL is required}"
export NEXT_PUBLIC_SUPABASE_URL="$SUPABASE_URL"
export NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY="${PUBLISHABLE_KEY:-${ANON_KEY:?A public Supabase key is required}}"
export SUPABASE_SERVICE_ROLE_KEY="${SERVICE_ROLE_KEY:-${SECRET_KEY:?A service-role key is required}}"
export LOCAL_WEB_URL='http://127.0.0.1:3000'
export PHASE5_WEB_URL="$LOCAL_WEB_URL"
export NEXT_TELEMETRY_DISABLED=1

npm run build
npm run start -w @student-law/web > "${RUNNER_TEMP:-/tmp}/student-law-web.log" 2>&1 &
web_pid=$!
ready=0
for _ in {1..45}; do
  if curl --fail --silent --output /dev/null "$LOCAL_WEB_URL"; then
    ready=1
    break
  fi
  sleep 2
done
if [[ "$ready" -ne 1 ]]; then
  echo 'The local frontend did not become ready.' >&2
  exit 1
fi

node scripts/check-local.mjs
node scripts/check-phase5-local.mjs
node scripts/ci-ingestion-failure.mjs
node scripts/ci-legislation-sync.mjs
node scripts/ci-search-latency.mjs
export CHROME_BIN="$(command -v google-chrome || command -v chromium || command -v chrome || true)"
node scripts/ci-accessibility.mjs
# Runs last because it deliberately exhausts this client's public API rate limit.
node scripts/ci-security-checks.mjs
